import type { TechPack } from "@/lib/schemas/tech-pack";

/**
 * AI visual asset prompt engineering for the technical pack.
 *
 * IMPORTANT:
 * These assets are intentionally generated by an AI image model.
 *
 * The prompts are designed to make the model behave like a technical
 * documentation renderer rather than a creative image generator.
 *
 * SOURCE OF TRUTH:
 *
 *   Reference image
 *      → visual appearance / observable geometry / colour / construction
 *
 *   Structured TechPack data
 *      → dimensions / POM / tolerances / materials / variants /
 *        construction / labels / compliance / exact text
 *
 * The AI must never invent missing information.
 */

export const VISUAL_ASSET_IDS = [
  "va-hero",
  "va-front",
  "va-back",
  "va-construction",
  "va-pom",
  "va-sizechart",
  "va-care",
  "va-materials",
] as const;

export type VisualAssetId = (typeof VISUAL_ASSET_IDS)[number];

export interface VisualAssetStatusLike {
  id: string;
  type?: string;
  status: string;
  asset_path?: string | null;
}

/**
 * True when the asset still needs a render.
 *
 * GENERATED without an asset path is treated as pending for backwards
 * compatibility with packs created before the AI-render queue existed.
 */
export function visualAssetPending(v: VisualAssetStatusLike): boolean {
  if (v.status === "GENERATED") return !v.asset_path;

  return v.status === "PLANNED" || v.status === "FAILED";
}

export interface VisualPromptContext {
  pack: TechPack;
  sizes: string[];
}

