/* -------------------------------------------------------------------------- */
/* DATA GROUNDING                                                             */
/* -------------------------------------------------------------------------- */

/**
 * Safely converts unknown values into displayable strings without changing
 * their meaning.
 */
function displayValue(value: unknown): string {
  if (value === null || value === undefined) return "—";

  if (typeof value === "string") return value;

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

/**
 * Build a flat, deterministic representation of the real TechPack data.
 *
 * IMPORTANT:
 * Do not aggressively slice arrays here.
 *
 * The image model needs the complete specification available to it.
 * Prompt length should be managed by the caller/model infrastructure,
 * not by silently deleting manufacturing information.
 */
export function summarizePackData(
  pack: TechPack,
  sizes: string[],
): string {
  const lines: string[] = [];

  /* ---------------------------------------------------------------------- */
  /* PRODUCT                                                                */
  /* ---------------------------------------------------------------------- */

  lines.push("# PRODUCT");

  lines.push(`PRODUCT NAME: ${displayValue(pack.product.name)}`);

  if (pack.product.category) {
    lines.push(`CATEGORY: ${displayValue(pack.product.category)}`);
  }

  if (pack.product.product_type) {
    lines.push(`PRODUCT TYPE: ${displayValue(pack.product.product_type)}`);
  }

  /* ---------------------------------------------------------------------- */
  /* COLOURWAYS                                                             */
  /* ---------------------------------------------------------------------- */

  if (pack.colorways.length) {
    lines.push("");
    lines.push("# COLORWAYS");

    for (const colorway of pack.colorways) {
      const faces = [
        colorway.face_a,
        colorway.face_b,
      ]
        .filter(Boolean)
        .join(" / ");

      const parts = [
        `NAME=${displayValue(colorway.name)}`,
        `CODE=${displayValue(colorway.code)}`,
      ];

      if (colorway.pantone) {
        parts.push(`PANTONE=${displayValue(colorway.pantone)}`);
      }

      if (faces) {
        parts.push(`FACES=${faces}`);
      }

      lines.push(`- ${parts.join(" | ")}`);
    }
  }

  /* ---------------------------------------------------------------------- */
  /* SIZES                                                                  */
  /* ---------------------------------------------------------------------- */

  if (sizes.length) {
    lines.push("");
    lines.push("# DEFINED SIZES / VARIANTS");

    sizes.forEach((size, index) => {
      lines.push(`${index + 1}. ${size}`);
    });
  }

  /* ---------------------------------------------------------------------- */
  /* MEASUREMENTS / POM                                                     */
  /* ---------------------------------------------------------------------- */

  if (pack.measurements.length) {
    lines.push("");
    lines.push("# MEASUREMENTS / POM");

    lines.push(
      "Each measurement below is factual structured data. " +
      "Do not invent or estimate values.",
    );

    for (const measurement of pack.measurements) {
      const values = sizes
        .filter((size) => measurement.values[size] !== undefined)
        .map(
          (size) =>
            `${size}=${displayValue(measurement.values[size])}`,
        )
        .join(", ");

      lines.push(
        [
          `ID=${displayValue(measurement.id)}`,
          `NAME=${displayValue(measurement.name)}`,
          `TOLERANCE=${displayValue(measurement.tolerance)}`,
          `VALUES=${values || "NO VALUE PROVIDED"}`,
        ].join(" | "),
      );
    }
  }

  /* ---------------------------------------------------------------------- */
  /* MATERIALS                                                              */
  /* ---------------------------------------------------------------------- */

  if (pack.materials.length) {
    lines.push("");
    lines.push("# MATERIALS");

    for (const material of pack.materials) {
      const composition =
        typeof material.composition?.value === "string"
          ? material.composition.value
          : undefined;

      const parts = [
        `NAME=${displayValue(material.name)}`,
        `TYPE=${displayValue(material.type)}`,
      ];

      if (composition) {
        parts.push(`COMPOSITION=${composition}`);
      }

      if (material.gsm?.value !== undefined) {
        parts.push(`GSM=${displayValue(material.gsm.value)}`);
      }

      if (material.color) {
        parts.push(`COLOR=${displayValue(material.color)}`);
      }

      lines.push(`- ${parts.join(" | ")}`);
    }
  }

  /* ---------------------------------------------------------------------- */
  /* CONSTRUCTION                                                           */
  /* ---------------------------------------------------------------------- */

  if (pack.construction.length) {
    lines.push("");
    lines.push("# CONSTRUCTION / ASSEMBLY");

    let globalStep = 1;

    for (const section of pack.construction) {
      for (const item of section.items) {
        lines.push(
          `${globalStep}. ${displayValue(item)}`,
        );

        globalStep += 1;
      }
    }
  }

  /* ---------------------------------------------------------------------- */
  /* LABELS                                                                 */
  /* ---------------------------------------------------------------------- */

  if (pack.labels.length) {
    lines.push("");
    lines.push("# LABELS");

    for (const label of pack.labels) {
      const parts = [
        `NAME=${displayValue(label.name)}`,
      ];

      if (label.placement) {
        parts.push(`PLACEMENT=${displayValue(label.placement)}`);
      }

      if (label.content) {
        parts.push(`CONTENT=${displayValue(label.content)}`);
      }

      lines.push(`- ${parts.join(" | ")}`);
    }
  }

  /* ---------------------------------------------------------------------- */
  /* CARE                                                                   */
  /* ---------------------------------------------------------------------- */

  const careLabels = pack.labels.filter((label) =>
    /care/i.test(label.name),
  );

  if (careLabels.length) {
    lines.push("");
    lines.push("# CARE / COMPLIANCE");

    for (const care of careLabels) {
      lines.push(
        `CARE LABEL: ${displayValue(care.name)}`,
      );

      if (care.content) {
        lines.push(
          `CARE CONTENT: ${displayValue(care.content)}`,
        );
      }

      if (care.placement) {
        lines.push(
          `CARE PLACEMENT: ${displayValue(care.placement)}`,
        );
      }
    }
  }

  return lines.join("\n");
}

