/* -------------------------------------------------------------------------- */
/* FINAL VALIDATION                                                           */
/* -------------------------------------------------------------------------- */

/**
 * This block is intentionally appended after the asset-specific instructions.
 *
 * The model should receive the validation criteria immediately before the
 * structured data so the final context it sees is precision-oriented.
 */
const FINAL_VALIDATION = `
# FINAL PRE-RENDER VALIDATION

Before rendering, internally verify the following:

PRODUCT
[ ] Correct product identity.
[ ] Silhouette matches the reference.
[ ] Proportions remain consistent.
[ ] No product redesign.

GEOMETRY
[ ] No component invented.
[ ] No component removed without evidence.
[ ] No impossible geometry.
[ ] No accidental symmetry.
[ ] No accidental perspective where orthographic projection is required.

DATA
[ ] Every required structured value is preserved.
[ ] No dimension was invented.
[ ] No tolerance was invented.
[ ] No material was invented.
[ ] No colour was invented.
[ ] No variant was invented.
[ ] No construction operation was invented.
[ ] No compliance symbol was invented.

TEXT
[ ] Identifiers are accurate.
[ ] Numbers are accurate.
[ ] Units are accurate.
[ ] Names are accurate.
[ ] No hallucinated labels.
[ ] No paraphrased exact technical strings.

CONSISTENCY
[ ] Asset belongs to the same product system as all other assets.
[ ] Geometry is consistent with the technical flats.
[ ] Materials correspond to the material data.
[ ] Measurements correspond to the POM data.
[ ] Variants correspond to the defined size system.

PRIORITY:

TRUTH > PRECISION > CONSISTENCY > COMPLETENESS > DECORATION

If information is uncertain:

OMIT IT.

Never fabricate information to make the artwork look complete.

Return ONLY the requested generated image.
`.trim();

/* -------------------------------------------------------------------------- */
/* PROMPT BUILDER                                                             */
/* -------------------------------------------------------------------------- */

/**
 * Build the complete AI prompt for one visual asset.
 *
 * Structure:
 *
 *   1. Asset identity
 *   2. Asset-specific rendering instructions
 *   3. Global technical-documentation system
 *   4. Final validation
 *   5. Complete structured pack data
 *
 * Putting the data last gives the model the actual values immediately after
 * the precision/validation rules.
 */
export function buildVisualPrompt(
  assetId: string,
  ctx: VisualPromptContext,
): string {
  const directive =
    DIRECTIVES[assetId as VisualAssetId] ??
    DIRECTIVES["va-hero"];

  const structuredData = summarizePackData(
    ctx.pack,
    ctx.sizes,
  );

  return [
    directive.headline,

    directive.body,

    GLOBAL_VISUAL_SYSTEM,

    FINAL_VALIDATION,

    "# STRUCTURED PACK DATA",
    "The following is the factual product specification.",
    "Use it as the authoritative source for every value rendered.",
    "Do not invent missing information.",
    "",
    structuredData,
  ].join("\n\n");
}
